def p(*texts):return ''.join('<p>'+x+'</p>' for x in texts)
def ul(*texts):return '<ul>'+''.join('<li>'+x+'</li>' for x in texts)+'</ul>'
def a(slug,text):return '<a href="'+slug+'.html">'+text+'</a>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+x+'</th>') if i==0 else '<td>'+x+'</td>' for i,x in enumerate(row))+'</tr>' for row in rows)+'</tbody></table>'

# Each entry is a page-specific editorial decision, not a keyword substitution.
EDITS={
'bang-gia-lai-xe-ho-da-nang':dict(intent='So sánh giá ô tô, xe máy và biết cách chốt tổng chi phí.',title='Bảng giá lái xe hộ Đà Nẵng: ô tô, xe máy | Như Ý Driver',intro='Lái hộ ô tô tại Đà Nẵng có giá tham khảo 150.000đ cho 0–5 km, 200.000đ cho 5–10 km; xe máy có bảng giá riêng bên dưới. Chọn đúng loại xe, xem phụ phí theo giờ đi và gửi hành trình để Như Ý Driver xác nhận tổng giá trước chuyến.',heading='Ví dụ tính giá ô tô cho một chuyến ban ngày',body=p('Với hành trình không có điểm ghé hay thời gian chờ thêm, bạn có thể dùng các ví dụ dưới đây để đọc bảng giá ô tô. Đây là phép tính theo biểu phí đang công bố, không phải báo giá cho mọi chuyến có cùng số km.')+table(['Quãng đường ví dụ','Cách đọc bảng','Giá tham khảo'],[('8 km','Thuộc khoảng 5–10 km','200.000đ'),('15 km','200.000đ + 5 × 15.000đ','275.000đ'),('Trên 30 km','Gửi hành trình để được báo giá riêng','Liên hệ')])+p('Ví dụ chưa cộng phụ phí khuya hoặc các khoản chờ, cầu đường, bãi xe nếu có. Với '+a('thue-tai-xe-theo-gio-da-nang','lịch thuê theo giờ')+' hay '+a('thue-tai-xe-theo-ngay-da-nang','theo ngày')+', hãy hỏi giá cho cả thời lượng sử dụng; không lấy bảng km để tự suy thành giá trọn gói.'),related=['lai-xe-ho-o-to-da-nang','lai-xe-ho-xe-may-da-nang','huong-dan-dat-tai-xe-nhu-y-driver'],summary='Bổ sung ví dụ 8/15 km, phân biệt giá km với thuê theo thời lượng, FAQ giá chờ và giữ nguyên các mức đã chốt.'),
'lai-xe-ho-o-to-da-nang':dict(intent='Đặt người lái chính ô tô của khách và hiểu việc bàn giao.',title='Lái hộ ô tô Đà Nẵng: bảng giá và cách đặt | Như Ý Driver',intro='Như Ý Driver cung cấp tài xế lái chính ô tô của khách tại Đà Nẵng, phù hợp khi bạn cần người lái thay sau tiệc hoặc trong lịch trình cá nhân. Gửi dòng xe, điểm đón, điểm đến và giờ đi qua 0985 666 044 hoặc Zalo để nhận xác nhận chuyến.',heading='Ô tô số sàn, số tự động hoặc xe có thao tác riêng: cần báo gì?',body=p('Khi đặt, đừng chỉ ghi “xe ô tô”. Dòng xe và kiểu hộp số giúp điều phối trao đổi người lái phù hợp; thao tác riêng của xe cần được nhắc lại lúc gặp, ngay trước khi khởi hành.')+table(['Thông tin xe','Nội dung nên trao đổi'],[('Dòng xe và hộp số','Tên xe, số sàn hoặc số tự động; các điểm cần lưu ý khi điều khiển.'),('Khởi động, khóa và phanh tay','Cách dùng chìa khóa, nút khởi động, phanh tay hoặc tính năng riêng.'),('Bãi xe và thẻ ra vào','Nơi đỗ, vé bãi, thẻ hoặc người mở cổng ở hai đầu chuyến.'),('Nhiên liệu và tình trạng xe','Mức nhiên liệu/pin và những dấu hiệu bất thường đã biết.')])+p('Nếu xe có vấn đề ảnh hưởng việc sử dụng, báo trước để thống nhất phương án thay vì mặc định nhận chuyến. Xem '+a('can-chuan-bi-gi-khi-ban-giao-xe','cách kiểm tra và bàn giao xe')+' để chuẩn bị đầy đủ.'),related=['bang-gia-lai-xe-ho-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','thue-tai-xe-theo-gio-da-nang'],summary='Làm rõ thuê người lái trên xe của khách; thêm bảng thông tin hộp số, thao tác, bãi xe và tình trạng phương tiện.'),
'lai-xe-ho-xe-may-da-nang':dict(intent='Biết cách bố trí người và xe máy, giá đúng loại phương tiện.',title='Lái hộ xe máy Đà Nẵng: giá và đặt tài xế | Như Ý Driver',intro='Bạn có xe máy tại điểm hẹn và cần người điều khiển thay? Như Ý Driver tiếp nhận yêu cầu lái hộ xe máy tại Đà Nẵng; hãy gửi loại xe, số người cần về, địa chỉ và giờ đi để thống nhất phương án cùng giá trước chuyến.',heading='Một xe nhưng nhiều người cần về: tách rõ hai nhu cầu',body=p('Số người cần di chuyển không quyết định chỉ từ số xe ở bãi. Khi gửi yêu cầu, nói rõ bạn cần đưa xe về, đưa người về hay cả hai; nếu nhóm có nhiều xe, liệt kê từng loại xe và người liên hệ.')+ul('Báo xe số, xe tay ga hay côn tay và ai đang giữ chìa khóa.','Nêu số người cần về và địa chỉ của từng người nếu khác nhau.','Chỉ bàn giao sau khi cách bố trí chuyến đã được xác nhận.','Nếu người đi cùng không thể ngồi vững, nhờ người thân hỗ trợ và trao đổi phương tiện phù hợp hơn.')+p('Nếu quyết định gửi lại xe, hỏi giờ lấy xe và phí bãi trước khi đi. Bài '+a('uong-ruou-bia-mang-theo-xe-may','đưa người và xe máy về sau buổi tiệc')+' giúp so sánh hai phương án.'),related=['bang-gia-lai-xe-ho-da-nang','uong-ruou-bia-mang-theo-xe-may','can-chuan-bi-gi-khi-ban-giao-xe'],summary='Bổ sung cách trao đổi khi nhiều người/một xe; làm rõ từng nhu cầu thay vì mặc định cách chở khách.'),
'lai-xe-ho-sau-tiec-da-nang':dict(intent='Đưa người và xe về sau tiệc bằng một kế hoạch rõ ràng.',title='Lái xe hộ sau tiệc Đà Nẵng: đặt đường về | Như Ý Driver',intro='Sau buổi tiệc, bạn có thể nhờ tài xế lái chính ô tô hoặc xe máy của mình về theo lộ trình đã thống nhất. Gửi Như Ý Driver nơi xe đỗ, điểm trả và giờ muốn về để xác nhận người lái, cách bố trí chuyến và chi phí.',heading='Cuối buổi tiệc, nên có một người phụ trách đặt chuyến',body=p('Khi cả nhóm cùng về, chỉ định một người giữ liên lạc sẽ tránh việc nhiều người gửi khác giờ đón hoặc địa chỉ trả. Người đó nên nắm cả vị trí xe, người giữ chìa khóa và danh sách các điểm xuống.')+ul('Trước lúc ra bãi: chốt người đi theo từng xe, điểm cuối và các chặng ghé.','Sau khi nhận phản hồi: kiểm tra giá, giờ đón dự kiến và thông tin tài xế.','Tại điểm gặp: đối chiếu người nhận xe, chuẩn bị vé bãi và chìa khóa.','Khi kế hoạch đổi: báo lại qua đầu mối đã đặt để kiểm tra lịch mới.')+p('Nếu tiệc kéo dài tới khuya, đọc '+a('dat-tai-xe-lai-ho-ban-dem-da-nang','hướng dẫn đặt tài xế ban đêm')+' để xem phần giờ khởi hành và phụ phí.'),related=['bang-gia-lai-xe-ho-da-nang','di-tiec-bang-o-to-da-nang','dat-tai-xe-lai-ho-ban-dem-da-nang'],summary='Bổ sung vai trò điều phối nhóm, thứ tự xác nhận và bàn giao sau tiệc; gắn đúng bài đêm và giá.'),
'thue-tai-xe-theo-gio-da-nang':dict(intent='Lập lịch theo thời lượng, biết thời gian chờ và cách hỏi tổng phí.',title='Thuê tài xế theo giờ Đà Nẵng: cách báo lịch | Như Ý Driver',intro='Thuê tài xế theo giờ phù hợp khi bạn có xe riêng và cần người lái qua nhiều điểm trong một khoảng thời gian. Gửi giờ bắt đầu, các chặng, thời gian chờ và giờ kết thúc để Như Ý Driver kiểm tra lịch và báo chi phí theo nhu cầu.',heading='Lập một lịch theo giờ để hỏi giá',body=table(['Mốc trong lịch','Thông tin cần gửi'],[('Bắt đầu','Giờ tài xế cần nhận xe, địa chỉ và người giao chìa khóa.'),('Giữa các cuộc hẹn','Thứ tự điểm ghé, khoảng chờ và nơi xe được phép đỗ.'),('Kết thúc','Địa chỉ trả xe và giờ dự kiến xong.'),('Dự phòng','Điểm có thể thay đổi hoặc cuộc hẹn chưa chắc giờ kết thúc.')])+p('Gửi lịch theo cách này giúp bạn hỏi rõ khoản nào đã bao gồm và cách tính khi kéo dài. Nếu chỉ cần đưa xe một lượt không chờ, nên hỏi thêm giá theo chuyến để so sánh, thay vì tự chọn gói dài hơn nhu cầu.'),related=['thue-tai-xe-theo-gio-hay-theo-ngay','thue-tai-xe-theo-ngay-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Thêm bảng lịch bắt đầu/chờ/kết thúc/dự phòng; tránh suy giá theo giờ từ bảng km.'),
'thue-tai-xe-theo-ngay-da-nang':dict(intent='Chuẩn bị cả ngày phục vụ và hỏi phạm vi gói trước khi đặt.',title='Thuê tài xế theo ngày Đà Nẵng: lịch và chi phí | Như Ý Driver',intro='Cần người lái xe riêng cho lịch công tác hoặc di chuyển kéo dài trong ngày? Gửi kế hoạch cho Như Ý Driver để kiểm tra khả năng bố trí, số giờ phục vụ, phạm vi hành trình và tổng phí trước khi chốt.',heading='Rà lại bốn mục khi nhận báo giá theo ngày',body=table(['Mục cần chốt','Câu hỏi nên trao đổi'],[('Thời lượng','Giờ bắt đầu, kết thúc; thời gian chờ và nghỉ được tính thế nào?'),('Hành trình','Các điểm ghé và lượt về nào đã có trong giá?'),('Chi phí khác','Bãi đỗ, cầu đường, ăn nghỉ nếu có do bên nào thanh toán?'),('Thay đổi','Đổi giờ, thêm điểm hoặc kéo dài lịch được cập nhật ra sao?')])+p('Một lịch gọi là “theo ngày” vẫn cần các giới hạn cụ thể. Hãy lưu lại nội dung đã thống nhất để người giao xe, hành khách và người điều phối đều biết phạm vi chuyến.'),related=['thue-tai-xe-theo-gio-hay-theo-ngay','thue-tai-xe-di-tinh-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Bổ sung bảng điều kiện gói ngày và trách nhiệm cập nhật lịch; không tự đặt mức giờ/km hoặc giá gói.'),
'thue-tai-xe-di-tinh-da-nang':dict(intent='Chuẩn bị hành trình xa, một chiều/khứ hồi và yêu cầu xe.',title='Thuê tài xế đi tỉnh từ Đà Nẵng: lịch và báo giá | Như Ý Driver',intro='Bạn có xe riêng và cần người lái thay cho hành trình xa từ Đà Nẵng? Gửi địa chỉ đến, ngày giờ, phương án một chiều hoặc khứ hồi và thời gian chờ để Như Ý Driver kiểm tra khả năng nhận lịch, sau đó xác nhận chi phí toàn chuyến.',heading='Một chiều và khứ hồi cần hai kế hoạch khác nhau',body=table(['Phương án','Thông tin cần làm rõ'],[('Kết thúc ở điểm đến','Ai nhận xe, chìa khóa và hoàn tất việc bàn giao?'),('Quay về trong ngày','Giờ đón về, nơi nhận lượt về và thời gian chờ giữa hai lượt.'),('Lịch qua đêm','Ngày về, thời lượng phục vụ và điều kiện ăn nghỉ nếu có.'),('Chưa chắc giờ về','Khoảng giờ dự kiến, phần lịch có thể đổi và cách báo lại.')])+p('Nếu bạn đang chuẩn bị chuyến tới '+a('thue-tai-xe-da-nang-di-hoi-an','Hội An')+' hoặc '+a('thue-tai-xe-da-nang-di-hue','Huế')+', xem bài hướng dẫn riêng để gửi đủ thông tin. Khả năng phục vụ từng hành trình cần được xác nhận, không suy từ tên tuyến.'),related=['thue-tai-xe-da-nang-di-hoi-an','thue-tai-xe-da-nang-di-hue','bang-gia-lai-xe-ho-da-nang'],summary='Thêm so sánh một chiều/khứ hồi/qua đêm và liên kết bài tuyến; làm rõ giờ về, người nhận xe.'),
'lai-xe-ho-la-gi':dict(intent='Hiểu người lái sử dụng xe nào và dịch vụ có phù hợp không.',title='Lái xe hộ là gì? Quy trình và khi nào nên gọi | Như Ý Driver',intro='Lái xe hộ là thuê tài xế điều khiển chính phương tiện của bạn theo chuyến đã thỏa thuận. Dịch vụ phù hợp khi cần đưa xe về sau tiệc hoặc muốn có người lái thay; bạn nên biết cách đặt, bàn giao và chốt chi phí trước khi sử dụng.',heading='Ai chuẩn bị phương tiện, ai giữ liên lạc?',body=table(['Việc trong chuyến','Điều cần thống nhất'],[('Chiếc xe','Khách đã có phương tiện ở điểm nhận và thông báo tình trạng xe.'),('Người lái','Điều phối xác nhận thông tin tài xế và thời gian đón dự kiến.'),('Lộ trình','Khách gửi điểm đi/đến, giờ đi, chặng ghé và yêu cầu chờ.'),('Bàn giao','Đối chiếu tài xế, giao chìa khóa và nhận lại xe cuối chuyến.')])+p('Nếu điều bạn cần là một chiếc xe đưa đón, hãy tìm phương án gồm cả phương tiện. Nếu đã có xe ở bãi, '+a('lai-xe-ho-o-to-da-nang','lái hộ ô tô')+' hoặc '+a('lai-xe-ho-xe-may-da-nang','lái hộ xe máy')+' là hai nội dung nên xem tiếp.'),related=['lai-xe-ho-va-taxi','huong-dan-dat-tai-xe-nhu-y-driver','bang-gia-lai-xe-ho-da-nang'],summary='Bổ sung bảng phân công phương tiện/người lái/liên hệ/bàn giao, giúp khách lần đầu hiểu đúng dịch vụ.'),
'truong-hop-nen-goi-tai-xe-lai-ho':dict(intent='Nhận ra tình huống phù hợp và lựa chọn cách đặt đúng.',title='7 trường hợp nên gọi tài xế lái hộ | Như Ý Driver',intro='Nên tìm người lái thay khi bạn không đủ điều kiện tự điều khiển xe hoặc cần dành thời gian cho một lịch trình khác. Bảy tình huống dưới đây giúp bạn chọn giữa lái hộ theo chuyến, thuê theo thời lượng và phương tiện đưa đón.',heading='Chọn cách đặt theo việc bạn thực sự cần',body=table(['Bạn cần gì?','Nội dung nên xem'],[('Đưa xe về một lượt sau buổi hẹn',a('lai-xe-ho-sau-tiec-da-nang','Lái xe hộ sau tiệc')+'.'),('Có người lái chờ qua nhiều cuộc hẹn',a('thue-tai-xe-theo-gio-da-nang','Thuê tài xế theo giờ')+'.'),('Lịch dài và có lượt quay về',a('thue-tai-xe-theo-ngay-da-nang','Tư vấn theo ngày')+' hoặc '+a('thue-tai-xe-di-tinh-da-nang','hành trình xa')+'.'),('Không có xe riêng ở điểm hẹn','Cân nhắc phương tiện đưa đón có xe phù hợp.')])+p('Khi liên hệ, mô tả tình huống cùng loại xe và lịch trình. Bạn không cần tự đoán tên gói: thông tin đầy đủ giúp điều phối tư vấn và kiểm tra khả năng phục vụ.'),related=['lai-xe-ho-sau-tiec-da-nang','thue-tai-xe-theo-gio-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Thêm bảng chọn theo nhu cầu, tránh dồn mọi tình huống về cùng một kiểu đặt chuyến.'),
'can-chuan-bi-gi-khi-ban-giao-xe':dict(intent='Kiểm tra xe trước/sau và làm rõ đầu mối trách nhiệm.',title='Bàn giao xe cho tài xế lái hộ: danh sách kiểm tra | Như Ý Driver',intro='Trước khi giao xe cho tài xế lái hộ, hãy đối chiếu đúng người nhận, kiểm tra tình trạng xe, chìa khóa, đồ dùng và hành trình. Danh sách dưới đây chia việc cần làm trước khi đi, lúc bàn giao và khi nhận lại xe để bạn dễ đối chiếu.',heading='Danh sách kiểm tra nhanh trước và sau chuyến',body=table(['Thời điểm','Những việc nên làm'],[('Trước khi tài xế đến','Chuẩn bị vị trí xe, chìa khóa, vé bãi và người liên lạc.'),('Khi gặp tài xế','Đối chiếu thông tin, ghi nhận tình trạng xe, nhắc thao tác riêng.'),('Trước lúc khởi hành','Chốt điểm trả, chặng ghé, nơi đỗ cuối và chi phí đã trao đổi.'),('Kết thúc','Nhận chìa khóa, kiểm tra đồ dùng và làm rõ vấn đề ngay khi bàn giao.')])+p('Nếu người đặt khác người giao hoặc nhận xe, nêu rõ từng người và số liên hệ. Với xe thuê/mượn, chỉ tiến hành sau khi điều kiện đổi người lái đã được chủ xe xác nhận.'),related=['huong-dan-dat-tai-xe-nhu-y-driver','thue-xe-tu-lai-goi-tai-xe','bang-gia-lai-xe-ho-da-nang'],summary='Thêm checklist theo thời điểm, sắp xếp phần trách nhiệm trước FAQ, bỏ lời văn ghi chú nội bộ.'),
'huong-dan-dat-tai-xe-nhu-y-driver':dict(intent='Chọn kênh liên hệ và gửi đủ dữ liệu để chuyến được xác nhận.',title='Cách đặt tài xế Như Ý Driver qua hotline, Zalo, web',intro='Bạn có thể đặt tài xế Như Ý Driver qua hotline 0985 666 044, Zalo hoặc biểu mẫu trên website. Chuẩn bị nơi xe đỗ, điểm đến, loại xe, giờ đi và số liên lạc; sau khi gửi, kiểm tra phản hồi xác nhận người lái và chi phí.',heading='Gửi yêu cầu xong, cần nhận lại những thông tin nào?',body=ul('Điểm nhận xe và giờ khởi hành đã được hiểu đúng.','Khả năng bố trí tài xế và thời gian đón dự kiến.','Tổng chi phí cho các chặng, thời gian chờ và khoản liên quan đã nêu.','Thông tin người nhận xe và kênh liên hệ khi đổi kế hoạch.')+p('Nếu thiếu phản hồi hoặc dữ liệu bản đồ chưa hiển thị, hãy liên hệ lại qua hotline/Zalo với cùng hành trình. Chưa có xác nhận chuyến thì không nên tự hiểu rằng đã bố trí xong tài xế. '+a('bang-gia-lai-xe-ho-da-nang','Bảng giá tham khảo')+' giúp bạn đối chiếu trước khi chốt.'),related=['bang-gia-lai-xe-ho-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','dat-tai-xe-lai-ho-ban-dem-da-nang'],summary='Bổ sung danh sách phản hồi cần nhận sau khi gửi form; chỉ rõ cách liên hệ khi bản đồ hoặc phản hồi chưa đủ.'),
'dat-tai-xe-lai-ho-ban-dem-da-nang':dict(intent='Đặt chuyến khuya rõ giờ, điểm đón và phụ phí.',title='Đặt tài xế lái hộ ban đêm Đà Nẵng: lưu ý và phí | Như Ý Driver',intro='Đặt lái xe hộ ban đêm tại Đà Nẵng cần rõ giờ đi, vị trí xe và người liên lạc. Như Ý Driver kiểm tra lịch trước khi xác nhận; ô tô có phụ phí 50.000đ trong khung 23:00–05:59 theo bảng giá hiện có.',heading='Khi buổi hẹn kéo dài, cập nhật những gì?',body=table(['Thay đổi','Nội dung cần báo lại'],[('Giờ khởi hành','Giờ mới và khoảng thời gian bạn thực sự sẵn sàng nhận tài xế.'),('Điểm gặp','Ghim mới, cổng hoặc bãi xe; xe có còn ở chỗ cũ không?'),('Số người và điểm trả','Các địa chỉ ghé thêm, thứ tự và loại xe.'),('Chi phí','Hỏi lại tổng phí theo giờ mới, khoản chờ hoặc chặng thêm nếu có.')])+p('Giữ một đầu mối liên hệ xuyên suốt để tài xế không nhận nhiều thông tin khác nhau. Hãy chờ điều phối xác nhận lại phương án sau khi đổi lịch.'),related=['bang-gia-lai-xe-ho-da-nang','lai-xe-ho-sau-tiec-da-nang','huong-dan-dat-tai-xe-nhu-y-driver'],summary='Thêm bảng cập nhật khi thay đổi giờ/điểm gặp; phân biệt phụ phí ô tô đã biết và giá phải xác nhận.'),
'buon-ngu-khi-lai-xe':dict(intent='Dừng hành trình phù hợp và bố trí người hỗ trợ.',title='Buồn ngủ khi lái xe: cách sắp xếp người lái thay | Như Ý Driver',intro='Nếu buồn ngủ hoặc khó giữ tập trung khi lái xe, hãy ưu tiên tìm vị trí dừng phù hợp rồi sắp xếp lại hành trình. Sau khi dừng, bạn có thể nhờ người đủ điều kiện lái thay hoặc kiểm tra dịch vụ lái hộ; đừng vừa điều khiển xe vừa tìm người hỗ trợ.',heading='Chọn người lái thay hay gửi xe lại?',body=table(['Điều kiện thực tế','Phương án cần cân nhắc'],[('Có người đi cùng đủ điều kiện lái','Trao đổi việc đổi người điều khiển sau khi xe đã dừng phù hợp.'),('Cần mang xe về cùng','Gửi vị trí và loại xe để kiểm tra lịch tài xế lái hộ.'),('Có nơi giữ xe được phép','Hỏi giờ lấy, phí bãi và bố trí phương tiện khác.'),('Chưa tìm được phương án','Nhờ người thân hỗ trợ sắp xếp lại, không lấy giờ đến nơi làm lý do cố chạy.')])+p('Giá và lịch của chuyến hỗ trợ cần được xác nhận trực tiếp. Bạn có thể xem '+a('bang-gia-lai-xe-ho-da-nang','giá lái hộ theo loại xe')+' sau khi đã có một vị trí dừng ổn định.'),related=['lai-xe-ho-o-to-da-nang','dat-tai-xe-lai-ho-ban-dem-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Thêm bảng phương án sau khi dừng; giữ trọng tâm nghỉ và bố trí hỗ trợ, không đưa mẹo chống buồn ngủ thiếu căn cứ.'),
'uong-ruou-bia-mang-theo-xe-may':dict(intent='Chọn cách đưa người và xe máy về sau tiệc.',title='Uống rượu bia mang xe máy: chọn đường về | Như Ý Driver',intro='Đã uống rượu bia và còn xe máy ở điểm hẹn, bạn nên sắp xếp người lái thay hoặc nơi gửi xe rồi dùng phương tiện khác. Hãy cân nhắc đồng thời việc người về và xe về, nhất là khi nhóm có nhiều người nhưng chỉ một chiếc xe.',heading='So sánh hai phương án trên cùng một kế hoạch',body=table(['Điều cần tính','Gọi lái hộ xe máy','Gửi xe lại'],[('Chiếc xe','Trao đổi phương án đưa xe tới địa chỉ đã chốt.','Hỏi chỗ giữ được phép, giờ mở bãi và vé nhận xe.'),('Người đi cùng','Báo đủ số người và khả năng di chuyển thực tế.','Chọn phương tiện đưa đón phù hợp với cả nhóm.'),('Chi phí','Hỏi giá xe máy, giờ đi, điểm trả và khoản chờ.','Tính phí gửi, lượt về nhà và lượt quay lại lấy xe.')])+p('Không lấy bảng giá ô tô để dự tính xe máy. Xem '+a('bang-gia-lai-xe-ho-da-nang','phần giá xe máy')+' rồi gửi thông tin để được xác nhận chuyến.'),related=['lai-xe-ho-xe-may-da-nang','bang-gia-lai-xe-ho-da-nang','lai-xe-ho-va-taxi'],summary='Thêm bảng so sánh gửi xe/lái hộ với cả nhu cầu người, xe và chi phí; liên kết đúng giá xe máy.'),
'di-tiec-bang-o-to-da-nang':dict(intent='Lên kế hoạch về nhà và xử lý ô tô trước buổi tiệc.',title='Đi tiệc bằng ô tô Đà Nẵng: chọn đường về | Như Ý Driver',intro='Nếu đi tiệc bằng ô tô và dự định không tự lái về, hãy chọn trước người lái thay hoặc chỗ gửi xe. Kế hoạch nên có giờ về, vị trí xe, các điểm trả khách và việc bạn có cần dùng ô tô vào sáng hôm sau hay không.',heading='Trước buổi tiệc, trao đổi nhanh với nhóm đi cùng',body=ul('Xe thuộc ai, ai giữ chìa khóa và vé bãi?','Những người nào về cùng, có chia nhiều địa chỉ không?','Địa điểm có nhận giữ ô tô qua đêm, giờ lấy xe thế nào?','Nếu gọi lái hộ, ai gửi yêu cầu và nhận phản hồi xác nhận?')+p('Chỉ định một người phụ trách giúp việc ra về gọn hơn. Khi cần người lái, gửi thông tin cho '+a('lai-xe-ho-sau-tiec-da-nang','dịch vụ sau tiệc')+' và hỏi tổng chi phí qua '+a('bang-gia-lai-xe-ho-da-nang','bảng giá ô tô')+' trước lúc chốt.'),related=['lai-xe-ho-sau-tiec-da-nang','lai-xe-ho-va-taxi','bang-gia-lai-xe-ho-da-nang'],summary='Bổ sung checklist thống nhất trong nhóm trước tiệc; làm rõ nơi giữ xe và nhu cầu dùng xe hôm sau.'),
'thue-tai-xe-theo-gio-hay-theo-ngay':dict(intent='So sánh hai cách thuê dựa trên tổng thời lượng và tổng giá.',title='Thuê tài xế theo giờ hay theo ngày? Cách chọn | Như Ý Driver',intro='Chọn thuê tài xế theo giờ hay theo ngày dựa vào số chặng, thời gian chờ và giờ kết thúc thực tế. Hãy yêu cầu hai phương án báo giá cho cùng một lịch trình để so sánh tổng phí và phạm vi phục vụ, thay vì chỉ nhìn đơn giá.',heading='Đọc hai báo giá theo cùng một danh sách',body=ul('Cùng loại xe và cùng các địa chỉ, thứ tự điểm ghé.','Cùng giờ bắt đầu, kết thúc và khoảng chờ dự kiến.','Cùng cách xử lý việc kéo dài, thêm điểm hoặc đổi giờ về.','Làm rõ phí đỗ xe, cầu đường và các khoản ngoài phần người lái.')+p('Nếu một phương án chưa nêu hết thời gian chờ, bạn chưa thể kết luận rẻ hơn. '+a('bang-gia-lai-xe-ho-da-nang','Giá theo quãng đường')+' là thông tin cho loại chuyến khác; không tự nhân mức km thành giá thuê cả buổi.'),related=['thue-tai-xe-theo-gio-da-nang','thue-tai-xe-theo-ngay-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Thêm checklist đối chiếu hai báo giá, không so đơn giá thiếu thời gian chờ hoặc tự quy đổi từ giá km.'),
'thue-xe-tu-lai-goi-tai-xe':dict(intent='Kiểm tra điều kiện đổi người lái trên xe thuê trước khi gọi dịch vụ.',title='Xe thuê tự lái có gọi tài xế lái thay được không? | Như Ý Driver',intro='Có thể nhờ tài xế lái thay xe thuê hay không phụ thuộc điều khoản sử dụng xe và xác nhận của bên cho thuê. Trước khi đặt, hãy hỏi việc bổ sung người lái, giấy tờ cần có và điều kiện bảo hiểm liên quan; không mặc định mọi xe thuê đều được phép.',heading='Gửi điều kiện của bên cho thuê cho người điều phối',body=p('Sau khi hỏi bên cho thuê, tập hợp phản hồi thành một nội dung ngắn để đầu mối bố trí tài xế kiểm tra. Tránh chỉ gửi dòng xe mà bỏ sót yêu cầu về người lái.')+ul('Xe nào, thời gian thuê và khoảng thời gian cần lái thay.','Bên cho thuê đã đồng ý nội dung gì; có cần bổ sung giấy tờ hay đăng ký người lái không.','Yêu cầu của hợp đồng liên quan đến người điều khiển và hành trình.','Người giao chìa khóa, người nhận xe và lịch trả xe đã thống nhất.')+p('Nếu điều kiện còn thiếu, trao đổi tiếp với bên cho thuê trước khi bàn giao. Xem '+a('can-chuan-bi-gi-khi-ban-giao-xe','các bước kiểm tra xe và chìa khóa')+' khi chuyến đã được xác nhận.'),related=['lai-xe-ho-o-to-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','bang-gia-lai-xe-ho-da-nang'],summary='Thêm cách chuyển xác nhận của bên cho thuê cho điều phối; phân biệt điều kiện người lái với quyền sử dụng xe.'),
'lai-xe-ho-va-taxi':dict(intent='So hai lựa chọn theo nhu cầu đưa xe về và tổng chi phí.',title='Lái xe hộ hay taxi: so chi phí và nhu cầu | Như Ý Driver',intro='Nếu cần đưa cả xe riêng về cùng, hãy cân nhắc lái xe hộ; nếu không có xe hoặc có thể gửi lại, taxi hay phương tiện đưa đón có thể phù hợp hơn. So sánh cần tính cả phí giữ xe, lượt lấy xe hôm sau và thời gian đón thực tế.',heading='Một ví dụ so sánh không cần đoán giá đối thủ',body=p('Bạn để ô tô ở nhà hàng và sáng hôm sau cần dùng xe. Với taxi, hãy tính lượt về nhà, phí giữ xe và lượt quay lại lấy ô tô. Với lái hộ, hỏi giá toàn hành trình bằng xe của bạn, bao gồm các chặng ghé và khoảng chờ đã nêu. Sau đó so hai tổng chi phí cùng mức thuận tiện.')+p('Nếu không cần ô tô ngay và bãi xe có điều kiện nhận phù hợp, kết quả cân nhắc có thể khác. '+a('bang-gia-lai-xe-ho-da-nang','Bảng giá lái hộ')+' là một đầu vào để hỏi chuyến; bài này không tự gán giá taxi hay khẳng định một phương án luôn rẻ hơn.'),related=['lai-xe-ho-la-gi','lai-xe-ho-sau-tiec-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Bổ sung ví dụ so tổng chi phí không bịa giá đối thủ; làm rõ chi phí quay lại lấy xe.'),
'thue-tai-xe-da-nang-di-hoi-an':dict(intent='Gửi đủ thông tin nhận/trả và lượt về cho hành trình Hội An.',title='Tài xế Đà Nẵng – Hội An: lịch chờ và báo giá | Như Ý Driver',intro='Muốn thuê người lái xe riêng cho hành trình Đà Nẵng – Hội An, hãy gửi địa chỉ nhận xe, điểm trả, ngày giờ và nhu cầu một chiều hoặc khứ hồi. Như Ý Driver kiểm tra khả năng nhận lịch rồi trao đổi tổng chi phí theo kế hoạch của bạn.',heading='Điểm trả khách và điểm nhận lượt về có thể khác nhau',body=p('Bạn có thể muốn xuống tại một địa chỉ rồi nhận xe ở địa chỉ khác sau buổi hẹn. Nếu vậy, gửi cả hai điểm, thời gian chuyển và ai giữ liên lạc; đừng chỉ ghi tên Hội An cho cả hành trình.')+table(['Phần lịch','Điều cần chốt'],[('Kết thúc lượt đi','Xe và người cùng dừng ở đâu; ai nhận chìa khóa nếu chỉ đi một chiều?'),('Trong lúc chờ','Xe đỗ tại vị trí nào được phép, tài xế có chờ cùng lịch không?'),('Lượt về','Giờ và địa chỉ nhận lại khách; các chặng ghé mới nếu có.')])+p('Nếu địa điểm có lối nhận riêng, hỏi người quản lý nơi đó về vị trí xe được phép tiếp cận và cập nhật cho điều phối.'),related=['thue-tai-xe-di-tinh-da-nang','thue-tai-xe-theo-ngay-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Thêm kế hoạch tách điểm trả/lượt về và nơi chờ; bỏ các câu hướng dẫn nội bộ, không công bố giá/giờ cố định.'),
'thue-tai-xe-da-nang-di-hue':dict(intent='Lên lịch theo giờ cần có mặt, xe và kế hoạch nghỉ/lượt về.',title='Tài xế Đà Nẵng – Huế: kế hoạch và chi phí | Như Ý Driver',intro='Thuê tài xế đi Huế bằng xe riêng cần rõ giờ hẹn ở điểm đến, loại xe, các chặng ghé và phương án về. Gửi kế hoạch cho Như Ý Driver để kiểm tra lịch phục vụ và báo chi phí; thời gian chạy được trao đổi theo hành trình thực tế.',heading='Khi chuyến có cuộc hẹn cố định, ưu tiên thông tin nào?',body=ul('Giờ cần có mặt và địa chỉ cụ thể, kể cả cổng nhận nếu có.','Các điểm phải ghé trước cuộc hẹn, người cần đón thêm.','Khoảng chờ, giờ kết thúc dự kiến và phương án quay về.','Điểm có thể linh hoạt nếu lịch thực tế thay đổi.')+p('Trao đổi với điều phối về kế hoạch khởi hành sau khi đã có những thông tin trên. Không dùng một con số giờ chạy chung để bỏ qua chặng ghé, nghỉ hoặc điều kiện thực tế. Nếu lịch kéo dài qua đêm, hỏi rõ cả thời lượng phục vụ và các khoản liên quan.'),related=['thue-tai-xe-di-tinh-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','bang-gia-lai-xe-ho-da-nang'],summary='Bổ sung thứ tự thông tin cho cuộc hẹn cố định, lịch chờ/về; bỏ cam kết trá hình và giá/giờ chạy thiếu căn cứ.'),
'thue-tai-xe-dua-don-doi-tac-da-nang':dict(intent='Điều phối ba vai trò và lịch khách trong chuyến có xe riêng.',title='Tài xế đưa đón đối tác Đà Nẵng: cách lên lịch | Như Ý Driver',intro='Để hỏi tài xế đưa đón đối tác bằng xe của bạn, hãy gửi lịch hẹn và phân biệt người đặt, người bàn giao xe, hành khách. Như Ý Driver sẽ kiểm tra khả năng bố trí cùng các yêu cầu riêng trước khi xác nhận người lái và giá.',heading='Bảng phân công liên lạc cho chuyến đưa đón',body=table(['Vai trò','Thông tin cần thống nhất'],[('Người đặt/duyệt lịch','Đầu mối nhận báo giá và xác nhận khi thêm chặng hoặc kéo dài.'),('Người giao xe','Vị trí xe, chìa khóa, vé bãi và cách nhận diện tài xế.'),('Hành khách hoặc người đón khách','Giờ có mặt, điểm gặp và số liên lạc cần thiết cho việc đón.'),('Người nhận cuối chuyến','Địa chỉ trả xe và người nhận chìa khóa nếu khác người đặt.')])+p('Hãy cập nhật thay đổi qua một đầu mối để người lái không nhận chỉ dẫn mâu thuẫn. Yêu cầu ngoại ngữ, nhiều xe hoặc giấy tờ thanh toán cần được hỏi riêng và chỉ coi là có khi đã nhận xác nhận.'),related=['thue-tai-xe-theo-gio-da-nang','thue-tai-xe-theo-ngay-da-nang','bang-gia-lai-xe-ho-da-nang'],summary='Thêm bảng phân công người duyệt/người giao/hành khách/người nhận; làm rõ yêu cầu ngoại ngữ, nhiều xe chưa mặc định cung cấp.'),
'tai-xe-phuc-vu-tiec-cuoi-su-kien-da-nang':dict(intent='Lập danh sách xe, người lái và từng giờ rời sự kiện.',title='Đặt tài xế tiệc cưới, sự kiện Đà Nẵng | Như Ý Driver',intro='Đặt tài xế cho tiệc cưới hoặc sự kiện cần danh sách từng xe, giờ rời tiệc, địa chỉ trả và người bàn giao. Gửi kế hoạch cho Như Ý Driver để kiểm tra số tài xế có thể bố trí; chưa có xác nhận thì chưa nên coi cả nhóm đã có người lái.',heading='Theo dõi từng xe đã được xác nhận tới bước nào',body=table(['Trạng thái của xe','Người phụ trách cần kiểm tra'],[('Đã gửi yêu cầu','Loại xe, hộp số, giờ đi và địa chỉ trả đủ chưa?'),('Đã được xác nhận','Thông tin tài xế, thời gian đón dự kiến và chi phí đã chốt.'),('Sẵn sàng bàn giao','Đúng xe, người giữ chìa khóa và hành khách đã ở điểm hẹn.'),('Có thay đổi','Báo đầu mối điều phối khi đổi giờ, thêm người hoặc đổi điểm trả.')])+p('Với nhóm rời tiệc không cùng lúc, cập nhật trạng thái theo từng xe thay vì dùng một thông báo chung. Số xe và số người lái cần khớp với phần đã được điều phối xác nhận.'),related=['lai-xe-ho-sau-tiec-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','bang-gia-lai-xe-ho-da-nang'],summary='Thêm bảng trạng thái từng xe; phân biệt đã gửi yêu cầu với đã có tài xế, không bịa năng lực đội xe.'),
'khu-vuc-phuc-vu':dict(intent='Tìm đúng trang khu vực và chọn điểm đón/trả cụ thể.',title='Khu vực lái xe hộ tại Đà Nẵng | Như Ý Driver',intro='Như Ý Driver tiếp nhận yêu cầu lái hộ tại các khu vực Đà Nẵng được liệt kê bên dưới. Chọn nơi xe đang đỗ để xem hướng dẫn riêng; sau đó gửi địa chỉ đón, điểm trả và giờ đi để kiểm tra lịch tài xế và chi phí.',heading='Đặt ở một khu vực, trả xe ở khu vực khác',body=p('Khu vực có xe và khu vực bạn muốn đến có thể khác nhau. Khi liên hệ, gửi cả hai đầu hành trình; nếu đang chờ ở nơi khác với chỗ đỗ xe, ghi thêm nơi gặp để bàn giao chìa khóa.')+table(['Vị trí cần làm rõ','Thông tin hữu ích'],[('Xe đang đỗ','Ghim, địa chỉ, cổng vào, tầng hầm hoặc tên bãi.'),('Người giao chìa khóa','Tên và số liên lạc nếu khác người đặt.'),('Điểm trả cuối','Địa chỉ, lối vào và người nhận nếu khách không đi cùng.'),('Điểm ngoài danh sách','Gửi yêu cầu để kiểm tra, không mặc định sẵn tài xế.')])+p('Bạn có thể xem '+a('bang-gia-lai-xe-ho-da-nang','bảng giá theo loại xe')+' trước khi gửi lịch. Với chuyến xa hoặc cần chờ, cần báo đủ hành trình để nhận giá phù hợp.'),related=['bang-gia-lai-xe-ho-da-nang','huong-dan-dat-tai-xe-nhu-y-driver','thue-tai-xe-di-tinh-da-nang'],summary='Bổ sung bảng đón/trả khác khu vực và đầu mối bàn giao; giảm danh sách lặp, giữ 6 thẻ địa bàn và ảnh đồng phục.'),
}

REGIONAL={
'lai-xe-ho-hai-chau-da-nang':dict(intent='Nhận xe ở bãi/hầm và đưa nhóm nhiều điểm từ Hải Châu.',title='Lái xe hộ Hải Châu Đà Nẵng: nhận xe và đặt chuyến | Như Ý Driver',intro='Cần đưa xe về từ khu vực Hải Châu sau buổi hẹn? Như Ý Driver tiếp nhận yêu cầu tài xế lái chính ô tô hoặc xe máy của khách. Gửi nơi xe đỗ, điểm trả và giờ đi để xác nhận người lái, thời gian đón dự kiến và chi phí.',heading='Ví dụ chuẩn bị một chuyến nhiều điểm từ Hải Châu',body=p('Bạn chờ ở địa điểm gặp mặt nhưng ô tô ở bãi khác, và nhóm cần xuống tại hai địa chỉ. Yêu cầu nên tách thành nơi gặp người giao chìa khóa, nơi nhận xe, thứ tự hai điểm trả và người liên lạc chính.')+ul('Chọn một người phụ trách để không gửi hai giờ đón khác nhau.','Nêu cổng hoặc tầng hầm nơi nhận ô tô, chuẩn bị vé bãi.','Liệt kê các điểm trả ngay khi hỏi giá và báo lại nếu đổi thứ tự.')+p('Nếu cần tài xế chờ qua nhiều cuộc hẹn, xem '+a('thue-tai-xe-theo-gio-da-nang','thuê tài xế theo giờ')+'; nếu chỉ đưa xe về sau liên hoan, xem '+a('lai-xe-ho-sau-tiec-da-nang','chuyến lái hộ sau tiệc')+'.'),related=['bang-gia-lai-xe-ho-da-nang','lai-xe-ho-sau-tiec-da-nang','thue-tai-xe-theo-gio-da-nang'],summary='Viết riêng ví dụ xe ở bãi khác và nhóm nhiều điểm; giảm hai đoạn đặt chuyến giống các trang khu vực khác.'),
'lai-xe-ho-son-tra-da-nang':dict(intent='Đón sau buổi hẹn muộn, chọn đúng xe và điểm nhận ở Sơn Trà.',title='Lái xe hộ Sơn Trà Đà Nẵng: đón xe sau hẹn | Như Ý Driver',intro='Có xe riêng tại Sơn Trà và cần người lái thay để về? Hãy gửi loại xe, vị trí bãi, điểm trả và giờ dự kiến cho Như Ý Driver. Tài xế sử dụng phương tiện của khách; cách bố trí người và xe được thống nhất trước chuyến.',heading='Chuẩn bị cho chuyến về muộn từ Sơn Trà',body=p('Trước khi rời địa điểm, xác định xe ở bãi nào và bạn sẽ gặp tài xế ở cổng nào. Nếu ghim đang chỉ chỗ bạn ngồi chứ chưa phải bãi xe, gửi thêm vị trí chiếc xe để hai bên không tìm sai điểm.')+table(['Nếu đi ô tô','Nếu đi xe máy'],[('Báo dòng xe, hộp số, số người và các địa chỉ trả.','Báo xe số/tay ga/côn tay, số người cần về và phương án đã thống nhất.'),('Chuẩn bị thẻ, vé bãi và thông tin hầm.','Chuẩn bị chìa khóa, vé xe và mũ bảo hiểm phù hợp.')])+p('Nếu giờ khởi hành thay đổi, hỏi lại tổng phí và giờ đón. '+a('dat-tai-xe-lai-ho-ban-dem-da-nang','Hướng dẫn chuyến ban đêm')+' nêu các thông tin cần cập nhật.'),related=['bang-gia-lai-xe-ho-da-nang','dat-tai-xe-lai-ho-ban-dem-da-nang','lai-xe-ho-xe-may-da-nang'],summary='Viết bảng chuẩn bị riêng ô tô/xe máy và điểm nhận khi về muộn; gắn hướng dẫn ban đêm thay đoạn chung.'),
'lai-xe-ho-cam-le-da-nang':dict(intent='Đón/trả ở nhà và phân biệt xe đang ở nhà hay nơi hẹn.',title='Lái xe hộ Cẩm Lệ – Hòa Xuân: đón và trả tại nhà | Như Ý Driver',intro='Như Ý Driver nhận thông tin lái hộ tại Cẩm Lệ hoặc Hòa Xuân bằng xe của khách. Cho biết xe đang ở nhà hay tại điểm hẹn, địa chỉ trả và ai giữ chìa khóa để kiểm tra lịch, thống nhất bàn giao và giá trước chuyến.',heading='Người đặt không trực tiếp giao hoặc nhận xe thì chuẩn bị gì?',body=table(['Vai trò','Nội dung cần gửi'],[('Người đặt','Lịch trình, giá đã thống nhất và đầu mối cập nhật thay đổi.'),('Người giao xe','Địa chỉ xe, chìa khóa, vé/thẻ và số liên lạc.'),('Người nhận ở nhà','Cổng, sân/gara, người mở cửa và vị trí được phép dừng.')])+p('Ví dụ, bạn nhờ người thân giao xe ở nhà rồi cần nhận lại tại nơi khác: phải báo đủ cả hai người và hai vị trí. Chỉ xác nhận bàn giao khi thông tin người lái và người giao/nhận đã khớp. '+a('can-chuan-bi-gi-khi-ban-giao-xe','Danh sách kiểm tra xe')+' giúp ghi lại các thao tác cần lưu ý.'),related=['bang-gia-lai-xe-ho-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','thue-tai-xe-theo-gio-da-nang'],summary='Bổ sung bảng người đặt/giao/nhận tại nhà, sửa câu địa chỉ lặp; giữ Cẩm Lệ và Hòa Xuân cùng một URL.'),
'lai-xe-ho-thanh-khe-da-nang':dict(intent='Chọn chuyến đơn hoặc có chờ cho lịch công việc ở Thanh Khê.',title='Lái xe hộ Thanh Khê: theo chuyến hoặc lịch có chờ | Như Ý Driver',intro='Cần đưa xe về từ Thanh Khê hoặc có người lái chờ qua các cuộc hẹn? Gửi Như Ý Driver nơi nhận xe, các điểm ghé và giờ kết thúc dự kiến. Điều phối kiểm tra lịch và tư vấn theo chuyến hoặc theo thời lượng phù hợp.',heading='Mẫu lịch ngắn để hỏi đúng loại báo giá',body=table(['Lịch bạn gửi','Cách trao đổi'],[('Từ điểm hẹn về một địa chỉ','Nêu giờ đi, loại xe và hai địa chỉ để hỏi một chuyến.'),('Ghép nhiều cuộc hẹn','Liệt kê thứ tự điểm ghé, thời gian chờ và giờ xong để hỏi theo thời lượng.'),('Chưa biết lúc tan việc','Nêu khoảng giờ, người giữ chìa khóa và cách báo lại giờ chính thức.')])+p('Một mức giá theo km chưa phản ánh thời gian chờ tại các cuộc hẹn. Nếu lịch chưa rõ, gửi kế hoạch đang có để '+a('thue-tai-xe-theo-gio-da-nang','hỏi tài xế theo giờ')+' và thống nhất cách cập nhật khi kéo dài.'),related=['bang-gia-lai-xe-ho-da-nang','thue-tai-xe-theo-gio-da-nang','thue-tai-xe-theo-gio-hay-theo-ngay'],summary='Bổ sung bảng chọn báo giá theo lịch đơn/nhiều điểm/chưa rõ giờ xong; tránh nhân bản nội dung địa bàn.'),
'lai-xe-ho-ngu-hanh-son-da-nang':dict(intent='Nhận xe ở nơi lưu trú và kiểm tra điều kiện xe thuê.',title='Lái xe hộ Ngũ Hành Sơn: nhận xe nơi lưu trú | Như Ý Driver',intro='Có xe riêng ở Ngũ Hành Sơn và cần người điều khiển thay? Gửi địa chỉ nơi xe đỗ, lối vào, điểm trả và giờ đi để Như Ý Driver kiểm tra lịch. Nếu là xe thuê tự lái, xác nhận điều kiện đổi người lái với bên cho thuê trước khi giao xe.',heading='Đặt từ nơi lưu trú: phân biệt xe của bạn và xe thuê',body=table(['Nội dung','Xe của bạn','Xe thuê tự lái'],[('Quyền bàn giao','Xác định người được giao và nhận chìa khóa.','Hỏi bên cho thuê về người lái bổ sung và điều kiện liên quan.'),('Điểm nhận xe','Gửi bãi, tầng hầm và cổng được phép vào.','Gửi cùng thông tin bãi và yêu cầu bàn giao của bên cho thuê.'),('Giờ hoàn tất','Chốt lịch trả xe cho người nhận.','Tính cả giờ cần trả xe theo thỏa thuận thuê.')])+p('Bạn có thể hỏi lễ tân hoặc quản lý về điểm gặp được phép, rồi gửi cho điều phối. '+a('thue-xe-tu-lai-goi-tai-xe','Hướng dẫn với xe thuê tự lái')+' nêu những câu cần làm rõ trước khi đặt.'),related=['bang-gia-lai-xe-ho-da-nang','thue-xe-tu-lai-goi-tai-xe','thue-tai-xe-da-nang-di-hoi-an'],summary='Bổ sung bảng xe riêng/xe thuê, giờ trả xe và lối nhận tại nơi lưu trú; giữ lưu ý hợp đồng đúng phạm vi.'),
'lai-xe-ho-lien-chieu-da-nang':dict(intent='Chốt điểm đón ổn định sau công việc hoặc hành trình xa.',title='Lái xe hộ Liên Chiểu: điểm đón và lịch về | Như Ý Driver',intro='Nếu cần người lái thay tại Liên Chiểu sau công việc hoặc một hành trình dài, gửi vị trí xe đã đỗ, điểm đến và giờ sẵn sàng cho Như Ý Driver. Điều phối kiểm tra khả năng nhận chuyến và báo lại giá, thông tin tài xế trước khi bàn giao.',heading='Đặt sau giờ làm hoặc chuyến dài: giữ điểm gặp ổn định',body=p('Nếu đã dừng tại bãi phù hợp, hãy giữ một vị trí để trao đổi và chờ phản hồi. Khi cần chuyển chỗ theo yêu cầu của nơi đỗ, gửi ghim mới ngay; không để người lái tìm theo vị trí cũ.')+ul('Xe ở trong cổng nơi làm: báo người giao chìa khóa và điều kiện ra vào.','Xe ở bãi ngoài: gửi tên bãi hoặc mốc gần xe, chiều di chuyển.','Bạn chưa rõ giờ xong việc: nêu khoảng dự kiến và cách cập nhật.','Bạn đang mệt: nhờ người đi cùng hỗ trợ liên lạc sau khi đã dừng phù hợp.')+p('Nếu chuyến về kéo dài qua giờ khuya, xem '+a('dat-tai-xe-lai-ho-ban-dem-da-nang','thông tin đặt chuyến ban đêm')+' và chốt lại phí theo giờ đi thực tế.'),related=['bang-gia-lai-xe-ho-da-nang','buon-ngu-khi-lai-xe','dat-tai-xe-lai-ho-ban-dem-da-nang'],summary='Viết riêng cách giữ điểm gặp sau ca làm/chuyến xa, chuyển bãi và cập nhật giờ; bỏ hai khối chung giữa các vùng.')
}
