def inner(el):return (el.text or '')+''.join(LH.tostring(c,encoding='unicode',method='html') for c in el)
def alt_for(src,old):
 for prefix,text in ALT.items():
  if Path(src).name.startswith(prefix):return text
 return old

pages=[]
for slug,edit in EDITS.items():
 file=Path(slug+'.html');source=file.read_text(encoding='utf-8');doc=LH.fromstring(source)
 reading=doc.xpath('//div[@class="reading"]')[0]
 # Remove the duplicated regional instructions, keeping each area's specific material.
 if slug in REGIONAL:
  for section in list(reading.xpath('./section')):
   h=section.xpath('./h2');heading=h[0].text_content() if h else ''
   if heading in ['Những yêu cầu có thể gửi cho Như Ý Driver','Đặt chuyến và xác nhận giá']:reading.remove(section)
 # Remove internal drafting language rather than publishing a note about missing evidence.
 for element in reading.xpath('.//p'):
  if not len(element):
   element.text=(element.text or '').replace('Bài hướng dẫn này không công bố một chính sách bảo hiểm hay bồi thường của Như Ý Driver. Những nội dung đó cần được hỏi và xác nhận trực tiếp trước khi nhận xe.','Nếu cần biết điều kiện bảo hiểm hoặc cách xử lý khi có sự cố, hỏi rõ đơn vị cung cấp trước khi giao xe và lưu nội dung đã thống nhất.').replace('Không có mức phí hoặc thời gian chạy cố định được áp dụng trong bài này.','Giá và giờ khởi hành cần trao đổi theo địa chỉ, ngày sử dụng và thời lượng của chuyến.').replace('Như Ý Driver cần kiểm tra lịch và khả năng bố trí theo kế hoạch thực tế. Nội dung này hướng dẫn cách gửi yêu cầu, không khẳng định có sẵn một số lượng tài xế hoặc đội xe cho mọi sự kiện.','Gửi số xe và từng giờ đi để Như Ý Driver kiểm tra lịch. Bạn nên chờ xác nhận cụ thể về số tài xế có thể bố trí trước khi thông báo phương án cho cả nhóm.').replace('Không mặc định mọi yêu cầu đều có thể thực hiện.','Hãy thống nhất cách bố trí phù hợp khi đặt chuyến.')
 # Avoid implying that a place-name alone establishes a service boundary or a fixed price.
 if slug=='lai-xe-ho-cam-le-da-nang':
  for el in reading.xpath('.//p'):
   if not len(el) and el.text:el.text=el.text.replace('Khi đặt xe, hãy nêu rõ điểm đón ở Cẩm Lệ hay Hòa Xuân, kèm đường và số nhà.','Nêu rõ điểm đón ở Cẩm Lệ hay Hòa Xuân, kèm ghim nơi xe đỗ.')
 if slug=='thue-tai-xe-di-tinh-da-nang':
  for el in reading.xpath('.//p'):
   if not len(el) and el.text:el.text=el.text.replace('Nếu dự định đi Hội An, Huế hoặc một điểm ngoài Đà Nẵng,','Nếu dự định đi Hội An, Huế hoặc một hành trình xa khác,')
 # Insert each page's practical section before its FAQ.
 sec=LH.fragment_fromstring('<section><h2>'+edit['heading']+'</h2>'+edit['body']+'</section>')
 faq_sections=reading.xpath('./section[details]')
 insertion=faq_sections[0] if faq_sections else next((x for x in reading.xpath('./section') if x.get('class')=='contact'),None)
 if insertion is not None:reading.insert(reading.index(insertion),sec)
 else:reading.append(sec)
 # More helpful price FAQs without guessing waiting rates or bike boundary rules.
 if slug=='bang-gia-lai-xe-ho-da-nang':
  q=faq_sections[0]
  q.append(LH.fragment_fromstring('<details><summary>Thời gian chờ và điểm ghé đã có trong bảng km chưa?</summary><p>Hãy gửi nhu cầu chờ và từng điểm ghé để được báo tổng phí. Bảng km không thay cho xác nhận những yêu cầu phát sinh của chuyến.</p></details>'))
  q.append(LH.fragment_fromstring('<details><summary>Thuê theo giờ hoặc theo ngày có tính như một lượt theo km không?</summary><p>Cần báo giá riêng theo thời lượng, lịch trình và khoảng chờ. Không tự nhân bảng km thành một gói theo giờ hoặc theo ngày.</p></details>'))
 # Put responsibility questions before FAQs in the handover guide.
 if slug=='can-chuan-bi-gi-khi-ban-giao-xe':
  resp=reading.xpath('./section[h2[@id="trach-nhiem-ban-giao"]]')
  if resp and faq_sections:
   node=resp[0];reading.remove(node);reading.insert(reading.index(faq_sections[0]),node)
 # Replace unhelpful meta questions with ordinary customer questions.
 for q in reading.xpath('.//summary'):
  if q.text=='Bài này có nghĩa tuyến luôn có tài xế không?':q.text='Làm sao biết ngày tôi cần có tài xế đi Hội An?'
  if q.text=='Có mức giá cố định Đà Nẵng – Huế trong bài không?':q.text='Muốn nhận giá cho chuyến Đà Nẵng – Huế cần gửi gì?'
  if q.text=='Trang này có nghĩa nhận mọi điểm Cẩm Lệ và Hòa Xuân không?':q.text='Cần xác nhận gì khi đặt đón tại Cẩm Lệ hoặc Hòa Xuân?'
 # Contextual related links, including the price page except on the price page itself.
 for section in list(reading.xpath('./section')):
  if section.xpath('./div[@class="related"]'):reading.remove(section)
 rel=LH.fragment_fromstring('<section><h2>Thông tin liên quan</h2><div class="related">'+''.join(a(s,LH.parse(s+'.html').xpath('//h1')[0].text_content()) for s in edit['related'])+'</div></section>')
 contact=next((s for s in reading.xpath('./section') if s.get('class')=='contact'),None)
 if contact is not None:reading.insert(reading.index(contact),rel)
 else:reading.append(rel)
 # Every long article gets a real HTML table of contents; preserve existing anchor IDs.
 for toc in list(reading.xpath('./nav[@class="toc"]')):reading.remove(toc)
 used=set(doc.xpath('//*[@id]/@id'));toc_links=[]
 for i,section in enumerate(reading.xpath('./section'),1):
  headings=section.xpath('./h2')
  if not headings or section.get('class')=='contact':continue
  h=headings[0]
  if section.get('id'):sid=section.get('id')
  elif h.get('id'):sid=h.get('id')
  else:
   sid='noi-dung-'+str(i)
   while sid in used:sid+='-moi'
   h.set('id',sid);used.add(sid)
  toc_links.append((sid,h.text_content()))
 toc=LH.fragment_fromstring('<nav class="toc" aria-label="Mục lục"><strong>Trong trang này</strong><ul>'+''.join('<li><a href="#'+sid+'">'+html.escape(label)+'</a></li>' for sid,label in toc_links)+'</ul></nav>')
 tags=reading.xpath('./nav[@class="topic-tags"]');at=reading.index(tags[0])+1 if tags else 0
 reading.insert(at,toc)
 article_schema=any(json.loads(s.text).get('@type')=='Article' for s in doc.xpath('//script[@type="application/ld+json"]'))
 if article_schema:
  metas=reading.xpath('./p[@class="editorial-meta"]')
  if not metas:reading.insert(at,LH.fragment_fromstring('<p class="editorial-meta">Biên soạn: Như Ý Driver · Cập nhật <time datetime="2026-10-28">28/10/2026</time></p>'))
  else:
   for meta in metas:
    for child in list(meta):meta.remove(child)
    meta.text='Biên soạn: Như Ý Driver · Cập nhật '
    time=LH.SubElement(meta,'time') if hasattr(LH,'SubElement') else None
    if time is None:
     from lxml.etree import SubElement
     time=SubElement(meta,'time')
    time.set('datetime','2026-10-28');time.text='28/10/2026'
 for image in reading.xpath('.//img'):
  image.set('alt',alt_for(image.get('src'),image.get('alt','')))
 # Main content is exported as source. The existing HTML shell remains untouched by the renderer.
 hero=doc.xpath('//div[contains(concat(" ",normalize-space(@class)," ")," hero ")]//img')[0]
 h1=doc.xpath('//h1')[0].text_content()
 desc=edit['intro'].split('. ')[0].rstrip('.')+'. '+('Xem hướng dẫn, cách đặt và nội dung cần trao đổi trước chuyến.' if slug!='bang-gia-lai-xe-ho-da-nang' else 'Xem giá xe máy, phụ phí và ví dụ tính chi phí.')
 # Descriptions are intentionally authored separately from the card excerpt.
 desc_map={
  'bang-gia-lai-xe-ho-da-nang':'Bảng giá ô tô, xe máy Như Ý Driver tại Đà Nẵng; phụ phí khuya, ví dụ 8/15 km và những khoản cần chốt trước chuyến. Hotline 0985 666 044.',
  'lai-xe-ho-o-to-da-nang':'Tài xế lái chính ô tô của khách tại Đà Nẵng. Xem giá tham khảo, cách đặt, thông tin hộp số và checklist bàn giao xe với Như Ý Driver.',
  'lai-xe-ho-xe-may-da-nang':'Lái hộ xe máy Đà Nẵng: giá riêng cho xe máy, thông tin loại xe, số người, điểm trả và cách thống nhất phương án trước khi nhận chuyến.',
  'can-chuan-bi-gi-khi-ban-giao-xe':'Checklist bàn giao xe cho tài xế lái hộ: đối chiếu người nhận, tình trạng xe, chìa khóa, lộ trình và đầu mối trách nhiệm trước và sau chuyến.',
  'huong-dan-dat-tai-xe-nhu-y-driver':'Đặt Như Ý Driver qua 0985 666 044, Zalo hoặc website. Có mẫu tin nhắn và danh sách thông tin cần nhận lại để xác nhận chuyến.'}
 desc=desc_map.get(slug,desc)
 pages.append({'file':file.name,'intent':edit['intent'],'title':edit['title'],'h1':h1,'description':desc,'intro':edit['intro'],'hero_alt':alt_for(hero.get('src'),hero.get('alt','')),'hero_src':hero.get('src'),'body_html':inner(reading),'article':article_schema,'modified':'2026-10-28','change_summary':edit['summary']})

Path('content').mkdir(exist_ok=True)
Path('content/pages.json').write_text(json.dumps({'version':1,'pages':sorted(pages,key=lambda p:p['file'])},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
